import { RendererThree } from './base/RendererThree';
import { getCheckBox } from './base/util'

export class Solution {
    div: HTMLDivElement
    renderer: RendererThree;
    m: number[] = [0, 0];
    t: number = 0.0;
    pts: Point[] = [];

    constructor(id: string) {
        this.div = document.getElementById(id) as HTMLDivElement;
        this.renderer = new RendererThree(id);
        this.renderer.mouseClickPost = (e) => this.mouseClick(e);
        this.renderer.render = (scene) => this.render(scene);
        this.initDom();
        this.init();
    }
    public initDom() {
        const div = document.createElement('div');
        div.style.position = 'absolute'
        this.div.appendChild(div);

        const resetBtn = document.createElement('button');
        resetBtn.textContent = 'reset';
        resetBtn.onclick = () => {
            this.reset();
            this.init();
        }
        div.append(resetBtn);


        const cBox = getCheckBox('grid');
        div.append(cBox.div);
        cBox.checkBox.checked = true;
        cBox.checkBox.onchange = () => {
            if (cBox.checkBox.checked === true) {
                this.renderer.showGrid = true;
            } else {
                this.renderer.showGrid = false;
            }
        }

        const axis = getCheckBox('axis');
        div.append(axis.div);
        axis.checkBox.checked = true;
        axis.checkBox.onchange = () => {
            if (axis.checkBox.checked === true) {
                this.renderer.showAxis = true;
            } else {
                this.renderer.showAxis = false;
            }
        }
    }
    public reset() {
        this.renderer.reset();
        this.t = 0.0;
        this.pts = [];

    }
    public init() {

        for(let i = -10; i < 25; i++) {
            for(let j = -10; j < 10; j++) {
                const p = new Point(i ,j ,Math.sin(i * j * 0.1) + 10 );
                this.pts.push(p);
                this.renderer.addPoint(p)
            }
        }


    }
    public render(scene): void {

        this.pts.forEach((v)=>{
            
            v.force = new Vector3(0.0, 0.0, -9.81)
            v.move(this.t, 0.985)
        });


        this.t +=0.001
    }
    public mouseMove(x: number, y: number): void {
        // this.m[0] = x - this.canvas.width * 0.5;
        // this.m[1] = y - this.canvas.height * 0.5;
    }
    public renderMouse(ctx) {
        // ctx.fillStyle = '#eee';
        // ctx.beginPath();
        // ctx.arc(this.m[0], this.m[1], 3, 0, Math.PI * 2.0)
        // ctx.closePath();
        // ctx.fill();
    }
    public mouseClick(e: MouseEvent): void {
        // const v = new Point(x, y, 0);
        // console.log(v)
        // this.pts.push(v);
        // console.log('ddd')

        // console.log(this.renderer.m)

        const v = this.renderer.m;
        const p = new Point(v.x, v.z, v.y)
        this.pts.push(p);
        this.renderer.addPoint(p);

    }
    public destroy() {
        this.renderer.destroy();
    }
}

class Point {
    public vec: Vector3;
    public velocity: Vector3;
    public force: Vector3 = new Vector3(0,0,0);
    public mass = 10;
    public r: number = 10;
    public damping = 0.99 - (Math.random() * 0.01)
    constructor(x, y, z ,ux = 0, uy = 0, uz = 0) {
        this.vec =      new Vector3(x, y, z)
        this.velocity = new Vector3(ux, uy, uz)

    }
    public move(dt: number, damping: number = 1) {


        this.velocity = multiply(this.velocity, this.damping);
        this.velocity = add(this.velocity,  multiply(this.force, (dt / this.mass )))
        this.vec = add(this.vec, multiply(this.velocity, dt));

        if (this.vec.z < 0) {
            this.vec.z = 0;
            if (this.velocity.z < 0) {
                this.velocity.z = -this.velocity.z;
            }
        }
    }
}


